cat > /tmp/ivx-apk-upload.env << 'EOF'
AWS_ACCESS_KEY_ID=AKIASAJBIV7CL5662E4E
AWS_SECRET_ACCESS_KEY=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
AWS_REGION=us-east-1
CLOUDFRONT_DISTRIBUTION_ID=E1C0DEI0VKCUYN
EOF
chmod 600 /tmp/ivx-apk-upload.env
source /tmp/ivx-apk-upload.env
rm -f /tmp/ivx-apk-upload.env
cd /home/user/rork-app/expo && node -e "
const { S3Client, PutObjectCommand } = require('@aws-sdk/client-s3');
const { CloudFrontClient, ListDistributionsCommand, CreateInvalidationCommand } = require('@aws-sdk/client-cloudfront');
const fs = require('fs');
const credentials = { accessKeyId: process.env.AWS_ACCESS_KEY_ID, secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY };
const s3 = new S3Client({ region: process.env.AWS_REGION, credentials });
const cf = new CloudFrontClient({ region: 'us-east-1', credentials });
const BUCKET = 'ivxholding.com';
const src = '/home/user/rork-app/android-ivx-holdings/app/build/outputs/apk/release/app-universal-release.apk';
const key = 'apk/ivx-holdings-v1.0.0.apk';
const latest = 'apk/ivx-holdings-latest.apk';
(async () => {
  await s3.send(new PutObjectCommand({ Bucket: BUCKET, Key: key, Body: fs.readFileSync(src), ContentType: 'application/vnd.android.package-archive' }));
  await s3.send(new PutObjectCommand({ Bucket: BUCKET, Key: latest, Body: fs.readFileSync(src), ContentType: 'application/vnd.android.package-archive' }));
  const resp = await cf.send(new ListDistributionsCommand({}));
  const dist = (resp.DistributionList?.Items || []).find((d) => (d.Aliases?.Items || []).some((a) => a.includes('ivxholding.com')));
  let invId = null;
  if (dist) {
    const inv = await cf.send(new CreateInvalidationCommand({ DistributionId: dist.Id, InvalidationBatch: { CallerReference: 'ivx-apk-' + Date.now(), Paths: { Quantity: 1, Items: ['/apk/*'] } } }));
    invId = inv.Invalidation?.Id;
  }
  console.log('Universal: https://ivxholding.com/' + key);
  console.log('Latest:    https://ivxholding.com/' + latest);
  console.log('Invalidation: ' + (invId || dist?.Id || 'none'));
})();
" 2>&1

